SELECT CAST(COUNT(*) AS REAL) / CAST((SELECT COUNT(*) FROM cards WHERE isTextless = 1) AS REAL) * 100
FROM cards
WHERE isTextless = 1 AND layout = 'normal';

SELECT COUNT(DISTINCT bond_id) AS connection_count
FROM connected
WHERE atom_id LIKE 'TR%_19' OR atom_id2 LIKE 'TR%_19';

SELECT borderColor
FROM cards
WHERE name = 'Ancestor''s Chosen';

SELECT CAST(SUM(CASE WHEN element = 'h' THEN 1 ELSE 0 END) AS REAL) / COUNT(*) AS percent
FROM atom
WHERE molecule_id = 'TR206';

SELECT team_fifa_api_id
FROM Team_Attributes
WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;

SELECT
    CAST(
        COUNT(CASE WHEN fd.language = 'French' AND (c.power IS NULL OR c.power = '*') THEN 1 END) AS REAL
    ) /
    CAST(
        COUNT(CASE WHEN c.power IS NULL OR c.power = '*' THEN 1 END) AS REAL
    ) * 100 AS percentage
FROM cards c
JOIN foreign_data fd ON fd.uuid = c.uuid;

SELECT CAST(
    COUNT(*) AS REAL
) / COUNT(p.id) * 100 AS percentage
FROM Player p
JOIN Player_Attributes pa ON pa.player_api_id = p.player_api_id
WHERE p.height < 180 AND pa.overall_rating > 70;

SELECT CAST(SUM(CASE WHEN gender_id = 2 THEN 1 ELSE 0 END) AS REAL) /
       CAST(SUM(CASE WHEN gender_id = 1 THEN 1 ELSE 0 END) AS REAL) AS ratio
FROM superhero;

SELECT EILName
FROM schools
WHERE ABS(Longitude) = (
    SELECT MAX(ABS(Longitude)) FROM schools
);

SELECT ViewCount, OwnerDisplayName
FROM posts
WHERE Title = 'Computer Game Datasets';

SELECT lat, lng
FROM circuits
WHERE name = 'Silverstone Circuit';

SELECT ViewCount
FROM posts
WHERE Title = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

SELECT CAST(
    COUNT(DISTINCT CASE WHEN Consumption > 528.3 THEN CustomerID END) AS REAL
) / COUNT(DISTINCT CustomerID) AS percentage
FROM yearmonth
WHERE Date = '201202';

SELECT CAST(
    COUNT(CASE WHEN c.country = 'Germany' AND r.name = 'European Grand Prix' THEN 1 END) AS REAL
) / COUNT(*) * 100 AS percentage
FROM races r
JOIN circuits c ON r.circuitId = c.circuitId
WHERE r.name = 'European Grand Prix';

